--Q1. Total revenue generated by male vs. female customers
SELECT
    gender,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY gender
ORDER BY total_revenue DESC;

--Q2. Customers who used a discount but spent more than the average purchase amount
SELECT
    customer_id,
    purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
  AND purchase_amount > (
      SELECT AVG(purchase_amount)
      FROM customer
  )
ORDER BY purchase_amount DESC;

--Q3. Top 5 products with the highest average review rating
SELECT
    item_purchased,
    ROUND(AVG(review_rating::numeric), 2) AS average_product_rating
FROM customer
GROUP BY item_purchased
ORDER BY average_product_rating DESC
LIMIT 5;

--Q4. Compare average purchase amounts between Standard and Express Shipping
SELECT
    shipping_type,
    ROUND(AVG(purchase_amount)::numeric, 2) AS average_purchase
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;

--Q5. Do subscribed customers spend more?
SELECT
    subscription_status,
    COUNT(customer_id) AS total_records,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_spend,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC;

--Q6. Top 5 products with the highest percentage of purchases using discounts
SELECT
    item_purchased,
    ROUND(
        100.0 * SUM(
            CASE WHEN discount_applied = 'Yes'
                 THEN 1 ELSE 0 END
        ) / COUNT(*), 2
    ) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;

--Q7. Segment customers into New, Returning and Loyal
WITH customer_type AS (
    SELECT
        customer_id,
        previous_purchases,
        CASE
            WHEN previous_purchases = 1 THEN 'New'
            WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS customer_segment
    FROM customer
)
SELECT
    customer_segment,
    COUNT(*) AS number_of_customers
FROM customer_type
GROUP BY customer_segment
ORDER BY number_of_customers DESC;

--Q8. Top 3 most purchased products within each category
WITH item_counts AS (
    SELECT
        category,
        item_purchased,
        COUNT(*) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY COUNT(*) DESC
        ) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT
    item_rank,
    category,
    item_purchased,
    total_orders
FROM item_counts
WHERE item_rank <= 3
ORDER BY category, item_rank;

--Q9. Are repeat buyers (more than 5 previous purchases) likely to subscribe?
SELECT
    subscription_status,
    COUNT(*) AS repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

--Q10. Revenue contribution of each age group
SELECT
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;

--Q11. Which age group makes the highest number of purchases?
SELECT
    age_group,
    COUNT(*) AS total_purchases,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase_amount
FROM customer
GROUP BY age_group
ORDER BY total_purchases DESC;

--Q12. Top 10 customers by previous purchases
SELECT
    customer_id,
    age,
    gender,
    previous_purchases,
    purchase_amount
FROM customer
ORDER BY previous_purchases DESC
LIMIT 10;

--Q13. Distribution of customers by purchase frequency
SELECT
    frequency_of_purchases,
    COUNT(*) AS total_records,
    ROUND(
        100.0 * COUNT(*) / SUM(COUNT(*)) OVER(),
        2
    ) AS percentage
FROM customer
GROUP BY frequency_of_purchases
ORDER BY total_records DESC;

--Q14. Which product categories generate the highest revenue?
SELECT
    category,
    SUM(purchase_amount) AS total_revenue,
    COUNT(*) AS total_purchases,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase
FROM customer
GROUP BY category
ORDER BY total_revenue DESC;

--Q15. Which products generate the highest revenue?
SELECT
    item_purchased,
    SUM(purchase_amount) AS total_revenue,
    COUNT(*) AS total_orders
FROM customer
GROUP BY item_purchased
ORDER BY total_revenue DESC
LIMIT 10;

--Q16. Which product categories receive the highest average ratings?
SELECT
    category,
    ROUND(AVG(review_rating::numeric), 2) AS avg_rating,
    COUNT(*) AS total_reviews
FROM customer
GROUP BY category
ORDER BY avg_rating DESC;

--Q17. Which payment method is most commonly used?
SELECT
    payment_method,
    COUNT(*) AS total_transactions,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY payment_method
ORDER BY total_transactions DESC;

--Q18. Which shipping method generates the highest revenue?
SELECT
    shipping_type,
    COUNT(*) AS total_orders,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_order_value
FROM customer
GROUP BY shipping_type
ORDER BY total_revenue DESC;

--Q19. Which season generates the highest revenue?
SELECT
    season,
    COUNT(*) AS total_purchases,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase
FROM customer
GROUP BY season
ORDER BY total_revenue DESC;

--Q20. Which top 10 locations generate the highest revenue?
SELECT
    location,
    COUNT(*) AS total_orders,
    SUM(purchase_amount) AS total_revenue,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase
FROM customer
GROUP BY location
ORDER BY total_revenue DESC
LIMIT 10;

--Q21. Which product categories are most popular in each season?
SELECT
    season,
    category,
    COUNT(*) AS total_purchases,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY season, category
ORDER BY season, total_purchases DESC;

--Q22. Do customers who use discounts spend more or less?
SELECT
    discount_applied,
    COUNT(*) AS total_orders,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY discount_applied;

--Q23. What percentage of customers have subscriptions?
SELECT
    subscription_status,
    COUNT(*) AS total_records,
    ROUND(
        100.0 * COUNT(*) / SUM(COUNT(*)) OVER(),
        2
    ) AS percentage
FROM customer
GROUP BY subscription_status;

--Q24. Which gender has the highest subscription rate?
SELECT
    gender,
    COUNT(*) AS total_records,
    SUM(
        CASE
            WHEN subscription_status = 'Yes' THEN 1
            ELSE 0
        END
    ) AS subscribed_records,
    ROUND(
        100.0 * SUM(
            CASE
                WHEN subscription_status = 'Yes' THEN 1
                ELSE 0
            END
        ) / COUNT(*),
        2
    ) AS subscription_rate
FROM customer
GROUP BY gender
ORDER BY subscription_rate DESC;

--Q25. Rank products by revenue within each category
WITH product_revenue AS (
    SELECT
        category,
        item_purchased,
        SUM(purchase_amount) AS total_revenue
    FROM customer
    GROUP BY category, item_purchased
)
SELECT
    category,
    item_purchased,
    total_revenue,
    RANK() OVER (
        PARTITION BY category
        ORDER BY total_revenue DESC
    ) AS revenue_rank
FROM product_revenue
ORDER BY category, revenue_rank;

--Q26. Divide purchases into Low, Medium and High Spending groups
SELECT
    CASE
        WHEN purchase_amount < 25 THEN 'Low Spending'
        WHEN purchase_amount BETWEEN 25 AND 75 THEN 'Medium Spending'
        ELSE 'High Spending'
    END AS spending_segment,
    COUNT(*) AS total_purchases,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY spending_segment
ORDER BY total_revenue DESC;

--Q27. Which colours are most popular among customers?
SELECT
    color,
    COUNT(*) AS total_purchases,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_purchase
FROM customer
GROUP BY color
ORDER BY total_purchases DESC
LIMIT 10;

